package com.poe.cache.model;

public class Tincture {
    /** Wiki page ID */
    private int pageId;
    /** Wiki page name */
    private String pageName;
    /** Cooldown in seconds */
    private double cooldown;
    /** Cooldown HTML display */
    private String cooldownHtml;
    /** Cooldown range average */
    private double cooldownRangeAverage;
    /** Cooldown range colour */
    private String cooldownRangeColour;
    /** Cooldown range maximum */
    private double cooldownRangeMaximum;
    /** Cooldown range minimum */
    private double cooldownRangeMinimum;
    /** Cooldown range text */
    private String cooldownRangeText;
    /** Debuff interval in seconds */
    private double debuffInterval;
    /** Debuff interval HTML display */
    private String debuffIntervalHtml;
    /** Debuff interval range average */
    private double debuffIntervalRangeAverage;
    /** Debuff interval range colour */
    private String debuffIntervalRangeColour;
    /** Debuff interval range maximum */
    private double debuffIntervalRangeMaximum;
    /** Debuff interval range minimum */
    private double debuffIntervalRangeMinimum;
    /** Debuff interval range text */
    private String debuffIntervalRangeText;

    public Tincture() {}

    public int getPageId() { return pageId; }
    public void setPageId(int pageId) { this.pageId = pageId; }
    public String getPageName() { return pageName; }
    public void setPageName(String pageName) { this.pageName = pageName; }
    public double getCooldown() { return cooldown; }
    public void setCooldown(double cooldown) { this.cooldown = cooldown; }
    public String getCooldownHtml() { return cooldownHtml; }
    public void setCooldownHtml(String cooldownHtml) { this.cooldownHtml = cooldownHtml; }
    public double getCooldownRangeAverage() { return cooldownRangeAverage; }
    public void setCooldownRangeAverage(double cooldownRangeAverage) { this.cooldownRangeAverage = cooldownRangeAverage; }
    public String getCooldownRangeColour() { return cooldownRangeColour; }
    public void setCooldownRangeColour(String cooldownRangeColour) { this.cooldownRangeColour = cooldownRangeColour; }
    public double getCooldownRangeMaximum() { return cooldownRangeMaximum; }
    public void setCooldownRangeMaximum(double cooldownRangeMaximum) { this.cooldownRangeMaximum = cooldownRangeMaximum; }
    public double getCooldownRangeMinimum() { return cooldownRangeMinimum; }
    public void setCooldownRangeMinimum(double cooldownRangeMinimum) { this.cooldownRangeMinimum = cooldownRangeMinimum; }
    public String getCooldownRangeText() { return cooldownRangeText; }
    public void setCooldownRangeText(String cooldownRangeText) { this.cooldownRangeText = cooldownRangeText; }
    public double getDebuffInterval() { return debuffInterval; }
    public void setDebuffInterval(double debuffInterval) { this.debuffInterval = debuffInterval; }
    public String getDebuffIntervalHtml() { return debuffIntervalHtml; }
    public void setDebuffIntervalHtml(String debuffIntervalHtml) { this.debuffIntervalHtml = debuffIntervalHtml; }
    public double getDebuffIntervalRangeAverage() { return debuffIntervalRangeAverage; }
    public void setDebuffIntervalRangeAverage(double debuffIntervalRangeAverage) { this.debuffIntervalRangeAverage = debuffIntervalRangeAverage; }
    public String getDebuffIntervalRangeColour() { return debuffIntervalRangeColour; }
    public void setDebuffIntervalRangeColour(String debuffIntervalRangeColour) { this.debuffIntervalRangeColour = debuffIntervalRangeColour; }
    public double getDebuffIntervalRangeMaximum() { return debuffIntervalRangeMaximum; }
    public void setDebuffIntervalRangeMaximum(double debuffIntervalRangeMaximum) { this.debuffIntervalRangeMaximum = debuffIntervalRangeMaximum; }
    public double getDebuffIntervalRangeMinimum() { return debuffIntervalRangeMinimum; }
    public void setDebuffIntervalRangeMinimum(double debuffIntervalRangeMinimum) { this.debuffIntervalRangeMinimum = debuffIntervalRangeMinimum; }
    public String getDebuffIntervalRangeText() { return debuffIntervalRangeText; }
    public void setDebuffIntervalRangeText(String debuffIntervalRangeText) { this.debuffIntervalRangeText = debuffIntervalRangeText; }
}
